#!/usr/bin/env python3
"""Red Team TASK-20261017-8aff64 -- own F_p review computations.

Everything here is written by the reviewer from the definitions: F_p / F_{p^2}
arithmetic, the Weierstrass group law, polynomial arithmetic over F_p (Yun +
distinct-degree factorisation), the fibre polynomial F(T) = S_m(x_1..x_{m-1},T)
for m = 3, 4 (from the reviewer's own S_4 table) and m = 5 (resultant of the
reviewer's S_4 fibre with S_3, by evaluation/interpolation), and the Frobenius
cycle-type sampling.  No code from experiments/ is imported.

Usage: rt_numeric.py symbolic_out.json out.json
"""
import json, random, sys, time, math, itertools

SYM = json.load(open(sys.argv[1]))
OUT = {"stages": {}, "notes": []}
T0 = time.time()

# ----------------------------------------------------------------- F_p basics
def legendre(a, p):
    a %= p
    if a == 0:
        return 0
    return 1 if pow(a, (p - 1) // 2, p) == 1 else -1

def sqrt_mod(a, p):
    """Tonelli-Shanks. a must be a QR (or 0)."""
    a %= p
    if a == 0:
        return 0
    if p % 4 == 3:
        r = pow(a, (p + 1) // 4, p)
        return r if r * r % p == a else None
    q, s = p - 1, 0
    while q % 2 == 0:
        q //= 2; s += 1
    z = 2
    while legendre(z, p) != -1:
        z += 1
    m, c, t, r = s, pow(z, q, p), pow(a, q, p), pow(a, (q + 1) // 2, p)
    while t != 1:
        i, tt = 0, t
        while tt != 1:
            tt = tt * tt % p; i += 1
        b = pow(c, 1 << (m - i - 1), p)
        m, c, t, r = i, b * b % p, t * b * b % p, r * b % p
    return r if r * r % p == a else None

def nonresidue(p):
    n = 2
    while legendre(n, p) != -1:
        n += 1
    return n

# ----------------------------------------------------------------- F_{p^2}
class F2:
    """F_{p^2} = F_p(w), w^2 = n (n a non-residue).  Elements (u, v) = u + v w.
    Frobenius: (u, v) -> (u, -v) because w^p = w * n^((p-1)/2) = -w."""
    def __init__(self, p):
        self.p = p
        self.n = nonresidue(p)
    def add(self, a, b):
        p = self.p; return ((a[0] + b[0]) % p, (a[1] + b[1]) % p)
    def sub(self, a, b):
        p = self.p; return ((a[0] - b[0]) % p, (a[1] - b[1]) % p)
    def neg(self, a):
        p = self.p; return ((-a[0]) % p, (-a[1]) % p)
    def mul(self, a, b):
        p = self.p
        return ((a[0] * b[0] + self.n * a[1] * b[1]) % p, (a[0] * b[1] + a[1] * b[0]) % p)
    def inv(self, a):
        p = self.p
        nrm = (a[0] * a[0] - self.n * a[1] * a[1]) % p
        i = pow(nrm, -1, p)
        return (a[0] * i % p, (-a[1]) * i % p)
    def frob(self, a):
        return (a[0], (-a[1]) % self.p)
    def is_zero(self, a):
        return a[0] == 0 and a[1] == 0
    def in_Fp(self, a):
        return a[1] == 0
    def emb(self, u):
        return (u % self.p, 0)
    def sqrt(self, u):
        """square root in F_{p^2} of u in F_p."""
        p = self.p
        if u % p == 0:
            return (0, 0)
        if legendre(u, p) == 1:
            return (sqrt_mod(u, p), 0)
        s = sqrt_mod(u * pow(self.n, -1, p) % p, p)   # u = n s^2 -> sqrt = s w
        return (0, s)
    def pow(self, a, e):
        r = (1, 0)
        while e:
            if e & 1:
                r = self.mul(r, a)
            a = self.mul(a, a); e >>= 1
        return r

# ----------------------------------------------------------------- curve / group law over F_{p^2}
class Curve:
    def __init__(self, p, a, b):
        self.p, self.a, self.b = p, a % p, b % p
        assert (4 * a ** 3 + 27 * b ** 2) % p != 0, "singular"
        self.K = F2(p)
        self.A2 = self.K.emb(self.a)
    def f(self, x):
        p = self.p
        return (x * x * x + self.a * x + self.b) % p
    def chi(self, x):
        return legendre(self.f(x), self.p)
    def lift(self, x):
        """the point (x, sqrt f(x)) in E(F_{p^2}) (one of the two)."""
        return (self.K.emb(x), self.K.sqrt(self.f(x)))
    def neg(self, P):
        if P is None:
            return None
        return (P[0], self.K.neg(P[1]))
    def add(self, P, Q):
        K = self.K
        if P is None: return Q
        if Q is None: return P
        if P[0] == Q[0]:
            if K.is_zero(K.add(P[1], Q[1])):
                return None
            # doubling
            num = K.add(K.mul(K.emb(3), K.mul(P[0], P[0])), self.A2)
            den = K.mul(K.emb(2), P[1])
        else:
            num = K.sub(Q[1], P[1]); den = K.sub(Q[0], P[0])
        lam = K.mul(num, K.inv(den))
        x3 = K.sub(K.sub(K.mul(lam, lam), P[0]), Q[0])
        y3 = K.sub(K.mul(lam, K.sub(P[0], x3)), P[1])
        return (x3, y3)
    def mul(self, k, P):
        R = None
        if k < 0:
            k, P = -k, self.neg(P)
        while k:
            if k & 1: R = self.add(R, P)
            P = self.add(P, P); k >>= 1
        return R
    def frob(self, P):
        if P is None: return None
        return (self.K.frob(P[0]), self.K.frob(P[1]))
    def random_Fp_point(self, rng):
        while True:
            x = rng.randrange(self.p)
            if self.chi(x) == 1:
                y = sqrt_mod(self.f(x), self.p)
                if rng.random() < 0.5: y = (-y) % self.p
                return (self.K.emb(x), self.K.emb(y))
    def random_twist_point(self, rng):
        """a point with x in F_p and y in w F_p (chi(f(x)) = -1)."""
        while True:
            x = rng.randrange(self.p)
            if self.chi(x) == -1:
                P = self.lift(x)
                return P if rng.random() < 0.5 else self.neg(P)
    def count_points(self):
        p = self.p
        Np = sum(1 for x in range(p) if self.chi(x) == 1)
        N0 = sum(1 for x in range(p) if self.chi(x) == 0)
        Nm = p - Np - N0
        return {"N_plus": Np, "N_minus": Nm, "N_zero": N0, "order": p + 1 + Np - Nm, "trace": -(Np - Nm)}

# ----------------------------------------------------------------- F_p[T]
def pnorm(a, p):
    a = [c % p for c in a]
    while a and a[-1] == 0:
        a.pop()
    return a
def pdeg(a):
    return len(a) - 1
def padd(a, b, p):
    n = max(len(a), len(b))
    return pnorm([(a[i] if i < len(a) else 0) + (b[i] if i < len(b) else 0) for i in range(n)], p)
def psub(a, b, p):
    n = max(len(a), len(b))
    return pnorm([(a[i] if i < len(a) else 0) - (b[i] if i < len(b) else 0) for i in range(n)], p)
def pmul(a, b, p):
    if not a or not b: return []
    r = [0] * (len(a) + len(b) - 1)
    for i, ai in enumerate(a):
        if ai:
            for j, bj in enumerate(b):
                r[i + j] += ai * bj
    return pnorm(r, p)
def pdivmod(a, b, p):
    a = pnorm(a, p); b = pnorm(b, p)
    assert b
    db = pdeg(b); inv = pow(b[-1], -1, p)
    q = [0] * max(0, len(a) - db)
    while a and pdeg(a) >= db:
        d = pdeg(a) - db; c = a[-1] * inv % p; q[d] = c
        for i in range(db + 1):
            a[d + i] = (a[d + i] - c * b[i]) % p
        a = pnorm(a, p)
    return pnorm(q, p), a
def pmonic(a, p):
    inv = pow(a[-1], -1, p); return [c * inv % p for c in a]
def pgcd(a, b, p):
    a, b = pnorm(a, p), pnorm(b, p)
    while b:
        a, b = b, pdivmod(a, b, p)[1]
    return pmonic(a, p) if a else a
def pderiv(a, p):
    return pnorm([i * a[i] for i in range(1, len(a))], p)
def ppowmod(base, e, mod, p):
    r, b = [1], pdivmod(base, mod, p)[1]
    while e:
        if e & 1: r = pdivmod(pmul(r, b, p), mod, p)[1]
        b = pdivmod(pmul(b, b, p), mod, p)[1]; e >>= 1
    return r
def peval(a, t, p):
    r = 0
    for c in reversed(a):
        r = (r * t + c) % p
    return r
def peval2(a, t, K):
    """evaluate F_p[T] polynomial at t in F_{p^2}."""
    r = (0, 0)
    for c in reversed(a):
        r = K.add(K.mul(r, t), K.emb(c))
    return r

def ddf_degrees(f, p):
    """f monic squarefree -> multiset of irreducible factor degrees."""
    out, i, h, fs = [], 1, [0, 1], f[:]
    while pdeg(fs) >= 2 * i:
        h = ppowmod(h, p, fs, p)
        g = pgcd(psub(h, [0, 1], p), fs, p)
        if pdeg(g) > 0:
            out += [i] * (pdeg(g) // i)
            fs = pdivmod(fs, g, p)[0]
            h = pdivmod(h, fs, p)[1] if pdeg(fs) > 0 else [0]
        i += 1
    if pdeg(fs) > 0:
        out.append(pdeg(fs))
    return sorted(out)

def yun(f, p):
    """Yun squarefree decomposition (char p > deg f): list of (factor, multiplicity)."""
    f = pmonic(f, p)
    fp = pderiv(f, p)
    assert fp, "derivative vanishes"
    c = pgcd(f, fp, p)
    w = pdivmod(f, c, p)[0]
    out, i = [], 1
    while pdeg(w) > 0:
        y = pgcd(w, c, p)
        z = pdivmod(w, y, p)[0]
        if pdeg(z) > 0:
            out.append((pmonic(z, p), i))
        i += 1; w = y
        c = pdivmod(c, y, p)[0]
    return out

def factor_pattern_mult(f, p):
    """irreducible factor degrees WITH multiplicity (the census's convention)."""
    f = pnorm(f, p)
    if pdeg(f) <= 0: return []
    degs = []
    for sf, m in yun(f, p):
        degs += ddf_degrees(sf, p) * m
    return sorted(degs)

def is_squarefree(f, p):
    f = pnorm(f, p)
    if pdeg(f) <= 0: return True
    d = pderiv(f, p)
    return bool(d) and pdeg(pgcd(f, d, p)) == 0

def label(parts):
    return "+".join(str(x) for x in parts) if parts else "(none)"

PART2CLASS = {(1, 1, 1, 1): "1^4", (1, 1, 2): "2+1+1", (2, 2): "2+2", (1, 3): "3+1", (4,): "4"}
def cls_name(proj):
    """census five-class name for a projective degree partition of 4."""
    return PART2CLASS.get(tuple(sorted(proj)), label(sorted(proj)))

# ----------------------------------------------------------------- own S_3 / S_4 tables
import sympy as sp
_x1, _x2, _x3, _x4, _a, _b, _e1, _e2, _e3 = sp.symbols('x1 x2 x3 x4 a b e1 e2 e3')
S4_TERMS = [(tuple(int(e) for e in mon), int(c)) for mon, c in sp.Poly(sp.sympify(SYM['S4']), _x1, _x2, _x3, _x4, _a, _b).terms()]
S4E_TERMS = {int(k): [(tuple(int(e) for e in mon), int(c)) for mon, c in sp.Poly(sp.sympify(v), _e1, _e2, _e3, _a, _b).terms()]
             for k, v in SYM['S4_T_coeffs_in_e'].items()}
OUT["S4_table_nterms"] = len(S4_TERMS)

def s3_coeffs_in_T(x1, x2, a, b, p):
    """S_3(x1, x2, T) as [c0, c1, c2] (own derivation)."""
    c2 = (x1 - x2) ** 2 % p
    c1 = (-2 * ((x1 + x2) * (x1 * x2 + a) + 2 * b)) % p
    c0 = ((x1 * x2 - a) ** 2 - 4 * b * (x1 + x2)) % p
    return [c0, c1, c2]

def s3_val(x1, x2, x3, a, b, p):
    return peval(s3_coeffs_in_T(x1, x2, a, b, p), x3, p)

class S4Table:
    """S_4 specialised to a curve: dict (i1,i2,i3,i4) -> coefficient mod p."""
    def __init__(self, E):
        p, a, b = E.p, E.a, E.b
        d = {}
        for (i1, i2, i3, i4, ia, ib), c in S4_TERMS:
            k = (i1, i2, i3, i4)
            d[k] = (d.get(k, 0) + c * pow(a, ia, p) * pow(b, ib, p)) % p
        self.terms = [(k, v) for k, v in d.items() if v]
        de = {}
        for k, terms in S4E_TERMS.items():
            lst = {}
            for (j1, j2, j3, ia, ib), c in terms:
                kk = (j1, j2, j3)
                lst[kk] = (lst.get(kk, 0) + c * pow(a, ia, p) * pow(b, ib, p)) % p
            de[k] = [(kk, v) for kk, v in lst.items() if v]
        self.eterms = de
        self.p = p
    def fibre(self, x1, x2, x3):
        """F(T) = S_4(x1,x2,x3,T) as coefficient list (low -> high)."""
        p = self.p
        P1 = [pow(x1, i, p) for i in range(5)]
        P2 = [pow(x2, i, p) for i in range(5)]
        P3 = [pow(x3, i, p) for i in range(5)]
        c = [0] * 5
        for (i1, i2, i3, i4), v in self.terms:
            c[i4] += v * P1[i1] * P2[i2] * P3[i3]
        return pnorm(c, p)
    def value(self, x1, x2, x3, x4):
        return peval(self.fibre(x1, x2, x3), x4, self.p)
    def fibre_sym(self, e1, e2, e3):
        """Q_e(T): the same polynomial with x1,x2,x3 the roots of X^3 - e1 X^2 + e2 X - e3."""
        p = self.p
        E1 = [pow(e1, i, p) for i in range(9)]
        E2 = [pow(e2, i, p) for i in range(9)]
        E3 = [pow(e3, i, p) for i in range(9)]
        c = [0] * 5
        for k, terms in self.eterms.items():
            s = 0
            for (j1, j2, j3), v in terms:
                s += v * E1[j1] * E2[j2] * E3[j3]
            c[k] = s % p
        return pnorm(c, p)

# ----------------------------------------------------------------- S_5 fibre by resultant
def det_mod(M, p):
    n = len(M); M = [row[:] for row in M]; det = 1
    for i in range(n):
        piv = None
        for r in range(i, n):
            if M[r][i] % p:
                piv = r; break
        if piv is None:
            return 0
        if piv != i:
            M[i], M[piv] = M[piv], M[i]; det = -det
        det = det * M[i][i] % p
        inv = pow(M[i][i], -1, p)
        for r in range(i + 1, n):
            if M[r][i] % p:
                fct = M[r][i] * inv % p
                for cidx in range(i, n):
                    M[r][cidx] = (M[r][cidx] - fct * M[i][cidx]) % p
    return det % p

def sylvester_res(A, B, dA, dB, p):
    """Formal resultant with formal degrees dA, dB (coefficient lists low->high, padded)."""
    A = A + [0] * (dA + 1 - len(A)); B = B + [0] * (dB + 1 - len(B))
    n = dA + dB
    M = []
    for i in range(dB):
        row = [0] * n
        for j in range(dA + 1):
            row[i + j] = A[dA - j]
        M.append(row)
    for i in range(dA):
        row = [0] * n
        for j in range(dB + 1):
            row[i + j] = B[dB - j]
        M.append(row)
    return det_mod(M, p)

def interpolate(points, p):
    """Lagrange interpolation over F_p: list of (t, v) -> coefficient list."""
    n = len(points); coeffs = [0] * n
    for i, (ti, vi) in enumerate(points):
        num = [1]; den = 1
        for j, (tj, _) in enumerate(points):
            if j != i:
                num = pmul(num, [(-tj) % p, 1], p); den = den * (ti - tj) % p
        s = vi * pow(den, -1, p) % p
        for k, c in enumerate(num):
            coeffs[k] = (coeffs[k] + s * c) % p
    return pnorm(coeffs, p)

def s5_value(tab, x1, x2, x3, x4, x5, a, b, p):
    """S_5(x1..x5) := Res_X( S_4(x1,x2,x3,X), S_3(x4,x5,X) ), formal degrees 4 and 2."""
    A = tab.fibre(x1, x2, x3)
    B = s3_coeffs_in_T(x4, x5, a, b, p)   # S_3(x4, x5, X) as poly in X (symmetric)
    return sylvester_res(A, B, 4, 2, p)

def s5_fibre(tab, x1, x2, x3, x4, a, b, p):
    """F(T) = S_5(x1,x2,x3,x4,T) by evaluation at 12 points and interpolation (deg <= 8)."""
    ts = []
    t = 0
    while len(ts) < 12:
        if t != x4 % p:
            ts.append(t)
        t += 1
    pts = [(t, s5_value(tab, x1, x2, x3, x4, t, a, b, p)) for t in ts]
    F = interpolate(pts, p)
    assert pdeg(F) <= 8, ("degree > 8", pdeg(F))
    # consistency: re-evaluate at two more points
    for t in (ts[-1] + 1, ts[-1] + 2):
        if t % p != x4 % p:
            assert peval(F, t, p) == s5_value(tab, x1, x2, x3, x4, t % p, a, b, p)
    return F

# ----------------------------------------------------------------- sign-class roots from the group law
def sign_roots(E, xs):
    """all x(P_1 + sum eps_i P_i), eps in {+-1}^{m-2}; returns list of (eps, x or None(=O))."""
    Ps = [E.lift(x) for x in xs]
    out = []
    for eps in itertools.product((1, -1), repeat=len(xs) - 1):
        S = Ps[0]
        for e, P in zip(eps, Ps[1:]):
            S = E.add(S, P if e == 1 else E.neg(P))
        out.append((eps, None if S is None else S[0]))
    return out

# ----------------------------------------------------------------- stage A: defining property
def stage_defining_property(E, tab, rng, n=200):
    p, a, b = E.p, E.a, E.b
    res = {}
    for m in (3, 4, 5):
        pos_ok = pos_tot = neg_ok = neg_tot = 0
        pos_fail, neg_fail = [], []
        for trial in range(n):
            # positive instance: m points summing to O, all on E(F_p) or all on the twist
            fam = rng.choice(('Fp', 'twist'))
            while True:
                Ps = [E.random_Fp_point(rng) if fam == 'Fp' else E.random_twist_point(rng) for _ in range(m - 1)]
                S = None
                for P in Ps: S = E.add(S, P)
                if S is not None:
                    break
            Pm = E.neg(S)
            xs = [P[0][0] for P in Ps] + [Pm[0][0]]
            assert all(P[0][1] == 0 for P in Ps + [Pm])
            if m == 3: v = s3_val(xs[0], xs[1], xs[2], a, b, p)
            elif m == 4: v = tab.value(*xs)
            else: v = s5_value(tab, *xs, a, b, p)
            pos_tot += 1
            if v == 0: pos_ok += 1
            elif len(pos_fail) < 5: pos_fail.append(xs)
            # negative / random instance: ground truth from the group law
            xs = [rng.randrange(p) for _ in range(m)]
            roots = [r for _, r in sign_roots(E, xs[:-1]) if r is not None]
            truth = any(r == (xs[-1], 0) for r in roots)
            if m == 3: v = s3_val(xs[0], xs[1], xs[2], a, b, p)
            elif m == 4: v = tab.value(*xs)
            else: v = s5_value(tab, *xs, a, b, p)
            neg_tot += 1
            if (v == 0) == truth: neg_ok += 1
            elif len(neg_fail) < 5: neg_fail.append((xs, truth, v))
        # also: planted hits -- x_m := a sign-class root, must vanish
        planted_ok = planted_tot = 0
        for trial in range(n):
            xs = [rng.randrange(p) for _ in range(m - 1)]
            roots = [r for _, r in sign_roots(E, xs) if r is not None and r[1] == 0]
            if not roots: continue
            xm = rng.choice(roots)[0]
            if m == 3: v = s3_val(xs[0], xs[1], xm, a, b, p)
            elif m == 4: v = tab.value(*xs, xm)
            else: v = s5_value(tab, *xs, xm, a, b, p)
            planted_tot += 1; planted_ok += (v == 0)
        res[f"m={m}"] = {"positive_sum_zero_tuples": [pos_ok, pos_tot], "random_tuples_truth_match": [neg_ok, neg_tot],
                         "planted_root_tuples_vanish": [planted_ok, planted_tot],
                         "positive_failures": pos_fail, "random_failures": neg_fail}
    return res

# ----------------------------------------------------------------- stage B: ordered-base Frobenius census at m = 4
TYPES4 = ["1^4", "2+2", "2+1+1", "4", "3+1"]
DENS = {
    "V4_regular": {"1^4": 1/4, "2+2": 3/4},
    "order2_double_transposition": {"1^4": 1/2, "2+2": 1/2},
    "C4": {"1^4": 1/4, "2+2": 1/4, "4": 1/2},
    "D4": {"1^4": 1/8, "2+2": 3/8, "2+1+1": 2/8, "4": 2/8},
    "A4": {"1^4": 1/12, "2+2": 3/12, "3+1": 8/12},
    "S4": {"1^4": 1/24, "2+1+1": 6/24, "2+2": 3/24, "3+1": 8/24, "4": 6/24},
    "S3_point_stabiliser": {"1^4": 1/6, "2+1+1": 3/6, "3+1": 2/6},
    "V4_nonregular_<(12),(34)>": {"1^4": 1/4, "2+1+1": 2/4, "2+2": 1/4},
}

def chisq_against(counts, n, dens):
    stat = 0.0; impossible = {}
    for t in TYPES4:
        q = dens.get(t, 0.0); o = counts.get(t, 0)
        if q == 0:
            if o: impossible[t] = o
            continue
        stat += (o - q * n) ** 2 / (q * n)
    return {"chi_square": round(stat, 3), "df": sum(1 for t in TYPES4 if dens.get(t, 0) > 0) - 1,
            "observed_in_classes_the_group_cannot_realise": impossible}

def ordered_census(E, tab, rng, n, exhaustive=False):
    p = E.p
    counts = {}; counts_nondeg = {}
    n_f0 = n_degdef = n_nonsqf = n_nondeg = 0
    rule_mismatch = []; rootcheck_fail = []; frob_fail = []
    pred_counts = {}
    deg_by_mech = {}
    allplus_types = {}
    ramified_label_counts = {}
    degdef_label_counts = {}
    it = itertools.product(range(p), repeat=3) if exhaustive else ((rng.randrange(p), rng.randrange(p), rng.randrange(p)) for _ in range(n))
    total = 0
    for (x1, x2, x3) in it:
        total += 1
        chis = (E.chi(x1), E.chi(x2), E.chi(x3))
        if 0 in chis:
            n_f0 += 1; continue
        F = tab.fibre(x1, x2, x3)
        deg = pdeg(F)
        sqf = is_squarefree(F, p)
        aff = factor_pattern_mult(F, p) if deg > 0 else []
        proj = sorted([1] * max(0, 4 - deg) + aff)
        lab = cls_name(proj)
        counts[lab] = counts.get(lab, 0) + 1
        if deg < 4:
            n_degdef += 1; degdef_label_counts[lab] = degdef_label_counts.get(lab, 0) + 1
        if not sqf:
            n_nonsqf += 1; ramified_label_counts[lab] = ramified_label_counts.get(lab, 0) + 1
        if deg == 4 and sqf:
            n_nondeg += 1
            counts_nondeg[lab] = counts_nondeg.get(lab, 0) + 1
            pred = "1^4" if (chis[0] == chis[1] == chis[2]) else "2+2"
            pred_counts[pred] = pred_counts.get(pred, 0) + 1
            if pred != lab and len(rule_mismatch) < 20:
                rule_mismatch.append({"x": [x1, x2, x3], "chi": chis, "pred": pred, "obs": lab, "F": F})
            if chis == (1, 1, 1):
                allplus_types[lab] = allplus_types.get(lab, 0) + 1
            # instrument B: group-law roots in F_{p^2}; F(r)=0; Frobenius acts as translation by delta'
            roots = sign_roots(E, (x1, x2, x3))
            K = E.K
            rl = [r for _, r in roots]
            if any(r is None for r in rl) or len(set(rl)) != 4:
                rootcheck_fail.append({"x": [x1, x2, x3], "reason": "O or repeated root on a fibre the table calls nondegenerate"})
            else:
                if any(not K.is_zero(peval2(F, r, K)) for r in rl):
                    if len(rootcheck_fail) < 20: rootcheck_fail.append({"x": [x1, x2, x3], "reason": "F(r) != 0"})
                d2, d3 = chis[0] * chis[1], chis[0] * chis[2]
                for (eps, r) in roots:
                    target_eps = (eps[0] * d2, eps[1] * d3)
                    r_t = dict(roots)[target_eps]
                    if K.frob(r) != r_t:
                        if len(frob_fail) < 20: frob_fail.append({"x": [x1, x2, x3], "eps": eps})
                        break
    cp = E.count_points()
    Np, Nm, N0 = cp["N_plus"], cp["N_minus"], cp["N_zero"]
    exact_1_4 = (Np ** 3 + Nm ** 3) / (Np + Nm) ** 3
    res = {
        "p": p, "a": E.a, "b": E.b, "point_count": cp, "mode": "exhaustive" if exhaustive else "random",
        "tuples": total, "tuples_with_some_f_zero_skipped": n_f0,
        "degree_deficient": n_degdef, "non_squarefree": n_nonsqf, "nondegenerate": n_nondeg,
        "label_counts_all_fibres_with_f_nonzero(census_convention)": counts,
        "label_counts_nondegenerate": counts_nondeg,
        "delta_rule_predicted_counts_nondegenerate": pred_counts,
        "delta_rule_mismatches": rule_mismatch,
        "ramified_label_counts": ramified_label_counts,
        "degree_deficient_label_counts": degdef_label_counts,
        "all_chi_plus_one_label_counts(PT-1 face)": allplus_types,
        "instrument_B_root_failures": rootcheck_fail,
        "instrument_B_frobenius_translation_failures": frob_fail,
        "freq_1^4_nondeg": counts_nondeg.get("1^4", 0) / max(1, n_nondeg),
        "exact_finite_p_prediction_1^4_(Np^3+Nm^3)/(Np+Nm)^3": exact_1_4,
        "binomial_se_at_1/4": math.sqrt(0.25 * 0.75 / max(1, n_nondeg)),
        "z_vs_exact": (counts_nondeg.get("1^4", 0) / max(1, n_nondeg) - exact_1_4) / math.sqrt(exact_1_4 * (1 - exact_1_4) / max(1, n_nondeg)),
        "z_vs_order2_group_(1/2)": (counts_nondeg.get("1^4", 0) / max(1, n_nondeg) - 0.5) / math.sqrt(0.25 / max(1, n_nondeg)),
        "chi_square_vs_candidates": {g: chisq_against(counts_nondeg, n_nondeg, d) for g, d in DENS.items()},
    }
    return res

# ----------------------------------------------------------------- stage C: symmetric-base Frobenius census at m = 4
def g_type(e1, e2, e3, p):
    g = [(-e3) % p, e2 % p, (-e1) % p, 1]
    return label(factor_pattern_mult(g, p)), is_squarefree(g, p), g

def symmetric_census(E, tab, rng, n, square_disc_only=False):
    p = E.p
    fpoly = [E.b, E.a, 0, 1]
    counts = {}; counts_nondeg = {}; joint = {}; joint_nondeg = {}
    n_res0 = n_grep = n_degdef = n_nonsqf = n_nondeg = 0
    struct_viol = []; odd_on_nondeg = []
    ram_by_class = {}; degdef_by_class = {}
    gsplit_label_sqf = {}
    drawn = 0
    while drawn < n:
        e1, e2, e3 = rng.randrange(p), rng.randrange(p), rng.randrange(p)
        gt, gsqf, g = g_type(e1, e2, e3, p)
        if square_disc_only:
            # disc of monic cubic X^3 + c2 X^2 + c1 X + c0 with c2=-e1, c1=e2, c0=-e3
            c2, c1, c0 = (-e1) % p, e2 % p, (-e3) % p
            disc = (18 * c2 * c1 * c0 - 4 * c2 ** 3 * c0 + c2 ** 2 * c1 ** 2 - 4 * c1 ** 3 - 27 * c0 ** 2) % p
            if legendre(disc, p) != 1:
                continue
        drawn += 1
        if pdeg(pgcd(g, fpoly, p)) > 0:
            n_res0 += 1; continue
        F = tab.fibre_sym(e1, e2, e3)
        deg = pdeg(F); sqf = is_squarefree(F, p)
        aff = factor_pattern_mult(F, p) if deg > 0 else []
        proj = sorted([1] * max(0, 4 - deg) + aff); lab = cls_name(proj)
        counts[lab] = counts.get(lab, 0) + 1
        jk = f"{gt} | {lab}"; joint[jk] = joint.get(jk, 0) + 1
        if deg < 4: n_degdef += 1; degdef_by_class[lab] = degdef_by_class.get(lab, 0) + 1
        if not sqf: n_nonsqf += 1; ram_by_class[lab] = ram_by_class.get(lab, 0) + 1
        if not gsqf: n_grep += 1
        if gt == "1+1+1" and lab == "2+1+1":
            k = "squarefree" if sqf else "non_squarefree"
            gsplit_label_sqf[k] = gsplit_label_sqf.get(k, 0) + 1
        if deg == 4 and sqf and gsqf:
            n_nondeg += 1
            counts_nondeg[lab] = counts_nondeg.get(lab, 0) + 1
            joint_nondeg[jk] = joint_nondeg.get(jk, 0) + 1
            # structural check: S_4 -> S_3 compatibility of the quartic class with g's type
            ok = {"1+1+1": {"1^4", "2+2"}, "1+2": {"2+1+1", "4"}, "3": {"3+1"}}[gt]
            if lab not in ok and len(struct_viol) < 20:
                struct_viol.append({"e": [e1, e2, e3], "g_type": gt, "class": lab, "F": F})
            if square_disc_only and lab in ("2+1+1", "4") and len(odd_on_nondeg) < 20:
                odd_on_nondeg.append({"e": [e1, e2, e3], "g_type": gt, "class": lab})
    res = {"p": p, "a": E.a, "b": E.b, "drawn": drawn, "excluded_Res(g,f)=0": n_res0, "g_non_squarefree": n_grep,
           "degree_deficient": n_degdef, "non_squarefree_F": n_nonsqf, "nondegenerate(F sqf deg 4, g sqf)": n_nondeg,
           "label_counts_all(census_convention)": counts, "label_counts_nondegenerate": counts_nondeg,
           "joint_gtype_class_all": joint, "joint_gtype_class_nondegenerate": joint_nondeg,
           "ramified_by_class": ram_by_class, "degree_deficient_by_class": degdef_by_class,
           "gsplit_2+1+1_by_squarefreeness": gsplit_label_sqf,
           "structure_violations_nondegenerate": struct_viol,
           "frequencies_nondegenerate": {t: counts_nondeg.get(t, 0) / max(1, n_nondeg) for t in TYPES4},
           "chi_square_vs_candidates": {g: chisq_against(counts_nondeg, n_nondeg, d) for g, d in DENS.items()}}
    if square_disc_only:
        res["odd_cycle_types_on_nondegenerate_fibres"] = odd_on_nondeg
        res["chi_square_vs_A4"] = chisq_against(counts_nondeg, n_nondeg, DENS["A4"])
    return res

# ----------------------------------------------------------------- stage D: OBS-1 exhaustive regeneration of the g-split block
def gsplit_block_exhaustive(E, tab):
    """all monic cubics over F_p that split completely (with multiplicity), as multisets {x1<=x2<=x3}."""
    p = E.p
    counts_label = {}; counts_2p1p1 = {"non_squarefree": 0, "squarefree_deg4": 0, "squarefree_deg3": 0}
    n_excl = 0; n_total = 0
    mech = {}
    examples = []
    for x1 in range(p):
        for x2 in range(x1, p):
            for x3 in range(x2, p):
                n_total += 1
                if E.chi(x1) == 0 or E.chi(x2) == 0 or E.chi(x3) == 0:
                    n_excl += 1; continue
                F = tab.fibre(x1, x2, x3)
                deg = pdeg(F); sqf = is_squarefree(F, p)
                aff = factor_pattern_mult(F, p) if deg > 0 else []
                proj = sorted([1] * max(0, 4 - deg) + aff); lab = cls_name(proj)
                # the census iterates ordered (e1,e2,e3); a multiset corresponds to exactly one e-triple
                counts_label[lab] = counts_label.get(lab, 0) + 1
                if lab == "2+1+1":
                    if not sqf:
                        counts_2p1p1["non_squarefree"] += 1
                        # mechanism: which signed pair lies in E[2]\{O} (x(P_i +- P_j) a root of f), or x_i = x_j
                        Ps = [E.lift(x) for x in (x1, x2, x3)]
                        reasons = []
                        for (i, j) in ((0, 1), (0, 2), (1, 2)):
                            for sgn in (1, -1):
                                S = E.add(Ps[i], Ps[j] if sgn == 1 else E.neg(Ps[j]))
                                if S is None:
                                    reasons.append(f"P{i+1}{'+' if sgn==1 else '-'}P{j+1}=O")
                                elif E.K.in_Fp(S[0]) and E.f(S[0][0]) == 0:
                                    reasons.append(f"P{i+1}{'+' if sgn==1 else '-'}P{j+1} in E[2]")
                        key = ";".join(reasons) if reasons else "other"
                        mech[key] = mech.get(key, 0) + 1
                        if len(examples) < 25:
                            examples.append({"x": [x1, x2, x3], "e": [(x1 + x2 + x3) % p, (x1 * x2 + x1 * x3 + x2 * x3) % p, (x1 * x2 * x3) % p],
                                             "chi": [E.chi(x1), E.chi(x2), E.chi(x3)], "F": F, "deg": deg, "affine_pattern_mult": aff, "reasons": reasons})
                    elif deg == 4:
                        counts_2p1p1["squarefree_deg4"] += 1
                        examples.append({"BREAK_CANDIDATE": True, "x": [x1, x2, x3], "F": F})
                    else:
                        counts_2p1p1["squarefree_deg3"] += 1
                        examples.append({"BREAK_CANDIDATE_deg3": True, "x": [x1, x2, x3], "F": F})
    return {"p": p, "a": E.a, "b": E.b, "multisets_total(C(p+2,3))": n_total, "excluded_some_f(x_i)=0": n_excl,
            "label_counts_gsplit_block": counts_label, "gsplit_2+1+1_breakdown": counts_2p1p1,
            "non_squarefree_2+1+1_mechanisms": mech, "examples": examples}

# ----------------------------------------------------------------- stage E: m = 5 delta-rule test
def m5_rule_test(E, tab, rng, n):
    p, a, b = E.p, E.a, E.b
    K = E.K
    n_f0 = n_deg = n_nondeg = 0; agree = 0; mism = []; types = {}; pred_types = {}; rootfail = []
    for _ in range(n):
        xs = [rng.randrange(p) for _ in range(4)]
        chis = [E.chi(x) for x in xs]
        if 0 in chis:
            n_f0 += 1; continue
        F = s5_fibre(tab, *xs, a, b, p)
        deg = pdeg(F); sqf = is_squarefree(F, p)
        if deg != 8 or not sqf:
            n_deg += 1; continue
        n_nondeg += 1
        pat = label(ddf_degrees(pmonic(F, p), p))
        pred = "1+1+1+1+1+1+1+1" if len(set(chis)) == 1 else "2+2+2+2"
        types[pat] = types.get(pat, 0) + 1; pred_types[pred] = pred_types.get(pred, 0) + 1
        if pat == pred: agree += 1
        elif len(mism) < 20: mism.append({"x": xs, "chi": chis, "pred": pred, "obs": pat})
        # instrument B on a subsample
        if n_nondeg % 10 == 1:
            roots = sign_roots(E, xs)
            rl = [r for _, r in roots]
            if any(r is None for r in rl) or len(set(rl)) != 8 or any(not K.is_zero(peval2(F, r, K)) for r in rl):
                if len(rootfail) < 10: rootfail.append({"x": xs})
            else:
                d = [chis[0] * c for c in chis[1:]]
                rd = dict(roots)
                for eps, r in roots:
                    te = tuple(e * dd for e, dd in zip(eps, d))
                    if K.frob(r) != rd[te]:
                        if len(rootfail) < 10: rootfail.append({"x": xs, "frob": "mismatch"})
                        break
    return {"p": p, "a": a, "b": b, "tuples": n, "skipped_f_zero": n_f0, "degenerate(deg<8 or non-squarefree)": n_deg,
            "nondegenerate": n_nondeg, "rule_agreements": agree, "mismatches": mism,
            "observed_types": types, "predicted_types": pred_types, "instrument_B_failures": rootfail,
            "freq_identity": types.get("1+1+1+1+1+1+1+1", 0) / max(1, n_nondeg),
            "chebotarev_(Z/2)^3_regular_identity_density": 1 / 8}

# ----------------------------------------------------------------- stage F: PT-2 numerics ([2]-graph at m = 3)
def pt2_test(E, rng, n=40):
    p, a, b = E.p, E.a, E.b
    rows = []; ok = 0; tot = 0
    while tot < n:
        x1 = rng.randrange(p)
        if E.chi(x1) == 0: continue
        P1 = E.lift(x1)
        P2 = E.add(P1, P1)
        if P2 is None: continue
        x2 = P2[0]
        assert E.K.in_Fp(x2)
        x2 = x2[0]
        if E.f(x2) == 0: continue
        F = s3_coeffs_in_T(x1, x2, a, b, p)
        deg = pdeg(F)
        pat = label(factor_pattern_mult(F, p)) if deg > 0 else "(none)"
        P3 = E.add(P2, P1)
        x3P = None if P3 is None else P3[0][0]
        roots_pred = sorted(set([x1] + ([x3P] if x3P is not None else [])))
        splits = (deg == 2 and all(d == 1 for d in factor_pattern_mult(F, p))) or (deg < 2)
        row = {"x1": x1, "chi_f_x1": E.chi(x1), "x2=x([2]P1)": x2, "chi_f_x2": E.chi(x2), "S3_coeffs": F, "deg": deg,
               "pattern_mult": pat, "predicted_roots": roots_pred, "F(x1)": peval(F, x1, p), "F(x3P1)": (peval(F, x3P, p) if x3P is not None else None),
               "splits_completely": splits}
        tot += 1; ok += (splits and E.chi(x2) == E.chi(x1))
        rows.append(row)
    return {"p": p, "a": a, "b": b, "n": tot, "complete_splitting_and_chi_equal": ok,
            "chi_minus_one_cases": sum(1 for r in rows if r["chi_f_x1"] == -1), "rows": rows}

# ----------------------------------------------------------------- stage G: group computation (sympy) for RA-2 orders
def symmetric_group_orders():
    from sympy.combinatorics import Permutation, PermutationGroup
    out = {}
    for m in range(3, 8):
        n = m - 1
        # points: sign classes = vectors in F_2^n modulo all-ones; normalise first coordinate to 0
        pts = [v for v in itertools.product((0, 1), repeat=n) if v[0] == 0]
        idx = {v: i for i, v in enumerate(pts)}
        def norm(v):
            return tuple((c + v[0]) % 2 for c in v)
        gens = []
        # translations by e_i
        for i in range(n):
            img = []
            for v in pts:
                w = list(v); w[i] ^= 1; img.append(idx[norm(tuple(w))])
            gens.append(Permutation(img))
        # adjacent transpositions of coordinates
        for i in range(n - 1):
            img = []
            for v in pts:
                w = list(v); w[i], w[i + 1] = w[i + 1], w[i]; img.append(idx[norm(tuple(w))])
            gens.append(Permutation(img))
        G = PermutationGroup(gens)
        transl = PermutationGroup(gens[:n])
        perms = PermutationGroup(gens[n:]) if n > 1 else PermutationGroup([Permutation(list(range(len(pts))))])
        info = {"m": m, "degree": len(pts), "order": G.order(), "formula_2^(m-2)(m-1)!": 2 ** (m - 2) * math.factorial(m - 1),
                "translation_image_order": transl.order(), "permutation_part_image_order": perms.order(),
                "transitive": G.is_transitive(), "primitive": G.is_primitive(), "abelian": G.is_abelian,
                "ordered_base_group_order_(translations)": transl.order(), "translations_regular": transl.is_transitive() and transl.order() == len(pts)}
        try:
            blocks = G.minimal_blocks()
            # describe block sizes
            sizes = []
            for bl in blocks:
                sz = {}
                for lbl in bl:
                    sz[lbl] = sz.get(lbl, 0) + 1
                sizes.append(sorted(sz.values()))
            info["minimal_block_systems_sizes"] = sizes
        except Exception as ex:
            info["minimal_blocks_error"] = repr(ex)
        if m == 4:
            from sympy.combinatorics.named_groups import SymmetricGroup
            info["equals_Sym(4)"] = (G.order() == 24 and G.degree == 4)
        # exponent of the group / cycle structure census for Chebotarev densities
        if G.order() <= 2000:
            ct = {}
            for g in G.elements:
                cyc = tuple(sorted(len(c) for c in g.full_cyclic_form))
                ct[label(cyc)] = ct.get(label(cyc), 0) + 1
            info["cycle_type_census"] = ct
        out[f"m={m}"] = info
    return out

# ================================================================= main
def main():
    out_path = sys.argv[2]
    rng_master = random.Random(20261017)
    seeds = {}
    def rng_for(name):
        s = rng_master.randrange(1 << 31); seeds[name] = s; return random.Random(s)

    curves = {
        "E_j0_p10009":   Curve(10009, 0, 7),      # a = 0, p = 1 mod 3 (ordinary, j = 0)
        "E_j1728_p10009": Curve(10009, 1, 0),     # b = 0, p = 1 mod 4 (ordinary, j = 1728)
        "E_ss_p10007":   Curve(10007, 0, 1),      # supersingular: p = 2 mod 3, y^2 = x^3 + 1
        "E_ss2_p10007":  Curve(10007, 1, 0),      # supersingular: p = 3 mod 4, y^2 = x^3 + x
        "E_gen_p10007":  Curve(10007, 2, 3),      # generic ordinary baseline
        "C1_p101":       Curve(101, 2, 3),        # census C1
        "C2_p101":       Curve(101, 1, 35),       # census C2
        "C3_p1009":      Curve(1009, 5, 7),       # census C3
        "C4_p1009":      Curve(1009, 2, 30),      # census C4
        "E_gen_p53":     Curve(53, 2, 3),         # small prime for an exhaustive ordered-base count
    }
    tabs = {k: S4Table(E) for k, E in curves.items()}
    OUT["curves"] = {k: {"p": E.p, "a": E.a, "b": E.b, **E.count_points()} for k, E in curves.items()}
    for k, E in curves.items():
        cp = OUT["curves"][k]
        cp["supersingular(trace=0)"] = (cp["trace"] == 0)
        cp["j_invariant"] = (1728 * 4 * E.a ** 3 * pow((4 * E.a ** 3 + 27 * E.b ** 2) % E.p, -1, E.p)) % E.p
    print("curves:", json.dumps(OUT["curves"], indent=0)); sys.stdout.flush()

    # --- stage G: group orders (curve-free), first since it is quick
    OUT["stages"]["G_symmetric_base_group_computation"] = symmetric_group_orders()
    print("G done", time.time() - T0); sys.stdout.flush()

    # --- stage A: defining property, 200 tuples per m, on two curves
    OUT["stages"]["A_defining_property"] = {}
    for k in ("E_gen_p10007", "E_j0_p10009"):
        OUT["stages"]["A_defining_property"][k] = stage_defining_property(curves[k], tabs[k], rng_for("A_" + k), n=200)
        print("A", k, json.dumps({m: {kk: v for kk, v in d.items() if 'fail' not in kk} for m, d in OUT["stages"]["A_defining_property"][k].items()}), time.time() - T0); sys.stdout.flush()

    # --- stage B: ordered base, m = 4
    OUT["stages"]["B_ordered_base_m4"] = {}
    plan = [("E_j0_p10009", 50000), ("E_j1728_p10009", 50000), ("E_ss_p10007", 50000), ("E_ss2_p10007", 20000), ("E_gen_p10007", 50000), ("C3_p1009", 20000), ("C4_p1009", 20000)]
    for k, n in plan:
        r = ordered_census(curves[k], tabs[k], rng_for("B_" + k), n)
        OUT["stages"]["B_ordered_base_m4"][k] = r
        print("B", k, {kk: r[kk] for kk in ("nondegenerate", "label_counts_nondegenerate", "freq_1^4_nondeg", "exact_finite_p_prediction_1^4_(Np^3+Nm^3)/(Np+Nm)^3", "z_vs_exact")}, "mismatches", len(r["delta_rule_mismatches"]), "B-fail", len(r["instrument_B_root_failures"]), len(r["instrument_B_frobenius_translation_failures"]), time.time() - T0); sys.stdout.flush()
    r = ordered_census(curves["E_gen_p53"], tabs["E_gen_p53"], None, 0, exhaustive=True)
    OUT["stages"]["B_ordered_base_m4"]["E_gen_p53_exhaustive"] = r
    print("B exhaustive p=53", {kk: r[kk] for kk in ("tuples", "nondegenerate", "label_counts_nondegenerate", "label_counts_all_fibres_with_f_nonzero(census_convention)", "ramified_label_counts", "degree_deficient_label_counts")}, time.time() - T0); sys.stdout.flush()

    # --- stage C: symmetric base, m = 4
    OUT["stages"]["C_symmetric_base_m4"] = {}
    for k, n in [("E_j0_p10009", 20000), ("E_j1728_p10009", 20000), ("E_ss_p10007", 20000), ("E_gen_p10007", 20000), ("C3_p1009", 20000), ("C4_p1009", 20000)]:
        r = symmetric_census(curves[k], tabs[k], rng_for("C_" + k), n)
        OUT["stages"]["C_symmetric_base_m4"][k] = r
        print("C", k, {kk: r[kk] for kk in ("nondegenerate(F sqf deg 4, g sqf)", "frequencies_nondegenerate", "gsplit_2+1+1_by_squarefreeness")}, "viol", len(r["structure_violations_nondegenerate"]), "chi2 S4", r["chi_square_vs_candidates"]["S4"], time.time() - T0); sys.stdout.flush()

    # --- stage D: OBS-1 exhaustive regeneration of the g-split block on C1 and C2
    OUT["stages"]["D_OBS1_gsplit_block_exhaustive"] = {}
    for k in ("C1_p101", "C2_p101"):
        r = gsplit_block_exhaustive(curves[k], tabs[k])
        OUT["stages"]["D_OBS1_gsplit_block_exhaustive"][k] = r
        print("D", k, {kk: r[kk] for kk in r if kk != "examples"}, time.time() - T0); sys.stdout.flush()

    # --- stage E: m = 5 rule test on two curves
    OUT["stages"]["E_m5_rule"] = {}
    for k, n in [("E_gen_p10007", 3000), ("E_j0_p10009", 3000)]:
        r = m5_rule_test(curves[k], tabs[k], rng_for("E_" + k), n)
        OUT["stages"]["E_m5_rule"][k] = r
        print("E", k, {kk: r[kk] for kk in r if kk not in ("mismatches", "instrument_B_failures")}, "mism", len(r["mismatches"]), "Bfail", len(r["instrument_B_failures"]), time.time() - T0); sys.stdout.flush()

    # --- stage F: PT-2 numerics
    OUT["stages"]["F_PT2"] = pt2_test(curves["E_gen_p10007"], rng_for("F_PT2"), n=40)
    print("F PT-2", {kk: OUT["stages"]["F_PT2"][kk] for kk in ("n", "complete_splitting_and_chi_equal", "chi_minus_one_cases")}, time.time() - T0); sys.stdout.flush()

    # --- stage H: PT-3 numerics (square-discriminant cubics, one curve, >= 2000)
    OUT["stages"]["H_PT3"] = symmetric_census(curves["E_gen_p10007"], tabs["E_gen_p10007"], rng_for("H_PT3"), 4000, square_disc_only=True)
    r = OUT["stages"]["H_PT3"]
    print("H PT-3", {kk: r[kk] for kk in ("nondegenerate(F sqf deg 4, g sqf)", "frequencies_nondegenerate", "chi_square_vs_A4")}, "odd", len(r["odd_cycle_types_on_nondegenerate_fibres"]), time.time() - T0); sys.stdout.flush()

    OUT["seeds"] = seeds
    OUT["elapsed_s"] = time.time() - T0
    OUT["python"] = sys.version
    import sympy; OUT["sympy_version"] = sympy.__version__
    json.dump(OUT, open(out_path, "w"), indent=1, default=str)
    print("wrote", out_path, "elapsed", time.time() - T0)

if __name__ == "__main__":
    main()

