#!/usr/bin/env python3
"""Larger ordered-base m=4 samples on the census curves C3, C4 (p = 1009), to
compare the S_4-based cycle-type sampling with the EXACT conditional expectation
from rt_exact_cond.py at tighter binomial error, plus a tuple-level cross-check
that the S_4-based nondegeneracy flag (squarefree, degree 4) agrees with the
group-law degeneracy characterisation (some P_i +- P_j in E[2] incl. O, or some
+-P1 +- P2 +- P3 = O) on a 20,000-tuple subsample per curve.
"""
import sys, json, random, time, math
sys.argv = ['x', '/tmp/claude-0/-home-user/d72a143b-1bef-500a-b9ca-d25907246d76/scratchpad/symbolic_out.json', '/dev/null']
sys.path.insert(0, '/tmp/claude-0/-home-user/d72a143b-1bef-500a-b9ca-d25907246d76/scratchpad')
import rt_numeric as R

def group_law_degenerate(E, xs):
    K = E.K
    Ps = [E.lift(x) for x in xs]
    for i in range(3):
        for j in range(i + 1, 3):
            if xs[i] == xs[j]:
                return True
            for Q in (E.add(Ps[i], Ps[j]), E.add(Ps[i], E.neg(Ps[j]))):
                if Q is None:
                    return True
                fx = K.add(K.add(K.mul(Q[0], K.mul(Q[0], Q[0])), K.mul(E.A2, Q[0])), K.emb(E.b))
                if K.is_zero(fx):
                    return True
    for e2 in (1, -1):
        for e3 in (1, -1):
            S = E.add(E.add(Ps[0], Ps[1] if e2 == 1 else E.neg(Ps[1])), Ps[2] if e3 == 1 else E.neg(Ps[2]))
            if S is None:
                return True
    return False

out = {}
t0 = time.time()
exact = {json.dumps([r['p'], r['a'], r['b']]): r for r in json.load(open('/tmp/claude-0/-home-user/d72a143b-1bef-500a-b9ca-d25907246d76/scratchpad/exact_cond_out.json'))}
for name, (p, a, b), seed in (("C3_p1009", (1009, 5, 7), 20261017101), ("C4_p1009", (1009, 2, 30), 20261017102)):
    E = R.Curve(p, a, b); tab = R.S4Table(E)
    rng = random.Random(seed)
    r = R.ordered_census(E, tab, rng, 200000)
    ex = exact[json.dumps([p, a, b])]
    q = ex['exact_conditional_freq_1^4']; n = r['nondegenerate']; k = r['label_counts_nondegenerate'].get('1^4', 0)
    r['exact_conditional_freq_1^4'] = q
    r['z_vs_exact_conditional'] = (k / n - q) / math.sqrt(q * (1 - q) / n)
    # tuple-level cross-check of the two degeneracy instruments on a fresh 20,000-tuple subsample
    rng2 = random.Random(seed + 1)
    agree = disagree = skipped = 0; examples = []
    for _ in range(20000):
        xs = [rng2.randrange(p) for _ in range(3)]
        if 0 in (E.chi(x) for x in xs):
            skipped += 1; continue
        F = tab.fibre(*xs)
        s4_nondeg = (R.pdeg(F) == 4 and R.is_squarefree(F, p))
        gl_nondeg = not group_law_degenerate(E, xs)
        if s4_nondeg == gl_nondeg:
            agree += 1
        else:
            disagree += 1
            if len(examples) < 10: examples.append({"x": xs, "s4_nondeg": s4_nondeg, "group_law_nondeg": gl_nondeg, "F": F})
    r['degeneracy_instrument_crosscheck_20000'] = {"agree": agree, "disagree": disagree, "skipped_f_zero": skipped, "examples": examples}
    r['seed'] = seed
    out[name] = r
    print(name, {kk: r[kk] for kk in ('nondegenerate', 'label_counts_nondegenerate', 'freq_1^4_nondeg', 'exact_conditional_freq_1^4', 'z_vs_exact_conditional')}, 'mism', len(r['delta_rule_mismatches']), 'xcheck', r['degeneracy_instrument_crosscheck_20000']['agree'], r['degeneracy_instrument_crosscheck_20000']['disagree'], time.time() - t0, flush=True)
out['elapsed_s'] = time.time() - t0
json.dump(out, open('/tmp/claude-0/-home-user/d72a143b-1bef-500a-b9ca-d25907246d76/scratchpad/big1009_out.json', 'w'), indent=1, default=str)
print('done', time.time() - t0)

